def natural_sort_strings(strings):
    """Sort strings by natural order: digit runs compared as integers, non-digit runs by Unicode order. Text tokens sort before numeric tokens. Shorter equal prefixes sort first; equal keys preserve input order."""
    def _key(s):
        parts = []
        i = 0
        n = len(s)
        while i < n:
            # Collect maximal contiguous digit run
            if s[i].isdigit():
                j = i
                while j < n and s[j].isdigit():
                    j += 1
                parts.append(('N', int(s[i:j])))
                i = j
            else:
                # Collect maximal contiguous non-digit run
                j = i
                while j < n and not s[j].isdigit():
                    j += 1
                parts.append(('T', s[i:j]))
                i = j
        return parts
    return sorted(strings, key=_key)
